//! The database URL of a project, as the CLI needs it (`migrate`, `doctor --db`).
//!
//! The application never reads a driver name: its driver is the feature the `karbon`
//! dependency is compiled with. The CLI is a separate binary, so it has to find out — and
//! a project generated by `karbon new` says it nowhere but in `app/Cargo.toml`.

use std::collections::HashMap;
use std::fs;
use std::path::Path;

/// The driver the project in `root` compiles with: `sqlite`, `postgres` or `mysql`
/// (the framework's default feature, hence also the answer when nothing says otherwise).
pub fn compiled_driver(root: &Path) -> &'static str {
    for dir in ["app", "api"] {
        if let Ok(content) = fs::read_to_string(root.join(dir).join("Cargo.toml")) {
            return driver_of_manifest(&content);
        }
    }
    "mysql"
}

fn driver_of_manifest(manifest: &str) -> &'static str {
    let dependency = manifest
        .lines()
        .find(|l| l.trim_start().starts_with("karbon ") || l.trim_start().starts_with("karbon="))
        .unwrap_or("");
    if dependency.contains("postgres") {
        "postgres"
    } else if dependency.contains("sqlite") {
        "sqlite"
    } else {
        "mysql"
    }
}

/// The connection URL described by the variables of a `.env`:
/// 1. `DATABASE_URL` when set;
/// 2. else built from `DB_*`, for the driver named by `DB_DRIVER` / `DB_CONNECTION` or,
///    failing that, `compiled_driver`.
///
/// `None` when no database is configured (`DB_NAME` empty or absent).
pub fn from_vars(vars: &HashMap<String, String>, compiled_driver: &str) -> Option<String> {
    let var = |keys: &[&str]| {
        keys.iter()
            .find_map(|k| vars.get(*k))
            .map(String::as_str)
            .filter(|v| !v.is_empty())
    };

    if let Some(url) = var(&["DATABASE_URL"]) {
        return Some(url.to_string());
    }

    let name = var(&["DB_NAME", "DB_DATABASE"])?;
    let driver = var(&["DB_DRIVER", "DB_CONNECTION"]).unwrap_or(compiled_driver);

    let (scheme, default_port, default_user) = match driver {
        // `mode=rwc` creates the file on first use, as the application does.
        "sqlite" | "sqlite3" => return Some(format!("sqlite://{name}?mode=rwc")),
        "postgres" | "postgresql" => ("postgres", "5432", "postgres"),
        _ => ("mysql", "3306", "root"),
    };

    let host = var(&["DB_HOST"]).unwrap_or("127.0.0.1");
    let port = var(&["DB_PORT"]).unwrap_or(default_port);
    let user = encode_userinfo(var(&["DB_USER", "DB_USERNAME"]).unwrap_or(default_user));
    let pass = encode_userinfo(var(&["DB_PASSWORD"]).unwrap_or(""));
    Some(format!("{scheme}://{user}:{pass}@{host}:{port}/{name}"))
}

/// The file behind a `sqlite:` URL, or `None` for another driver or an in-memory database.
pub fn sqlite_file(url: &str) -> Option<&str> {
    let rest = url.strip_prefix("sqlite:")?;
    let path = rest.trim_start_matches("//").split('?').next().unwrap_or("");
    if path.is_empty() || path == ":memory:" { None } else { Some(path) }
}

/// Percent-encode a database user or password for the userinfo part of a URL, as
/// `karbon::config::Config::database_url` does: `@ : / ? #`… no longer break the URL, and
/// `%` is kept so a value already encoded by hand produces the same URL as before.
pub fn encode_userinfo(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' => out.push(byte as char),
            b'-' | b'.' | b'_' | b'~' | b'%' | b'!' | b'$' | b'&' | b'\'' | b'(' | b')' | b'*' | b'+' | b',' | b';'
            | b'=' => out.push(byte as char),
            _ => out.push_str(&format!("%{byte:02X}")),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vars(pairs: &[(&str, &str)]) -> HashMap<String, String> {
        pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
    }

    /// What `karbon new` writes: no `DB_DRIVER`, no `DATABASE_URL`. `karbon migrate` used
    /// to answer "DATABASE_URL not found" to exactly this.
    #[test]
    fn a_freshly_generated_project_resolves_without_a_driver_variable() {
        let sqlite = vars(&[("DB_NAME", "app.db")]);
        assert_eq!(from_vars(&sqlite, "sqlite").as_deref(), Some("sqlite://app.db?mode=rwc"));

        let mysql = vars(&[
            ("DB_HOST", "127.0.0.1"),
            ("DB_PORT", "3306"),
            ("DB_NAME", "shop"),
            ("DB_USER", "root"),
            ("DB_PASSWORD", ""),
        ]);
        assert_eq!(from_vars(&mysql, "mysql").as_deref(), Some("mysql://root:@127.0.0.1:3306/shop"));

        let postgres = vars(&[("DB_NAME", "shop"), ("DB_USER", "app"), ("DB_PASSWORD", "p@ss")]);
        assert_eq!(from_vars(&postgres, "postgres").as_deref(), Some("postgres://app:p%40ss@127.0.0.1:5432/shop"));
    }

    #[test]
    fn an_empty_db_name_means_no_database() {
        assert_eq!(from_vars(&vars(&[("DB_NAME", ""), ("DB_USER", "root")]), "mysql"), None);
        assert_eq!(from_vars(&vars(&[]), "sqlite"), None);
    }

    #[test]
    fn explicit_settings_win_over_the_compiled_driver() {
        let url = vars(&[("DATABASE_URL", "postgres://u:p@db/x"), ("DB_NAME", "ignored")]);
        assert_eq!(from_vars(&url, "sqlite").as_deref(), Some("postgres://u:p@db/x"));

        let driver = vars(&[("DB_DRIVER", "postgres"), ("DB_NAME", "x")]);
        assert_eq!(from_vars(&driver, "mysql").as_deref(), Some("postgres://postgres:@127.0.0.1:5432/x"));

        let connection = vars(&[("DB_CONNECTION", "mariadb"), ("DB_DATABASE", "x"), ("DB_USERNAME", "u")]);
        assert_eq!(from_vars(&connection, "sqlite").as_deref(), Some("mysql://u:@127.0.0.1:3306/x"));
    }

    #[test]
    fn the_driver_is_read_from_the_karbon_dependency() {
        let dep = |attrs: &str| {
            format!("[dependencies]\nkarbon = {{ package = \"karbon-framework\", {attrs} }}\nsqlx.workspace = true\n")
        };
        assert_eq!(driver_of_manifest(&dep(r#"version = "0.5.1", features = ["studio"]"#)), "mysql");
        assert_eq!(
            driver_of_manifest(&dep(r#"version = "0.5.1", default-features = false, features = ["sqlite", "studio"]"#)),
            "sqlite"
        );
        assert_eq!(
            driver_of_manifest(&dep(r#"path = "../karbon", default-features = false, features = ["postgres"]"#)),
            "postgres"
        );
        assert_eq!(driver_of_manifest("[dependencies]\nserde = \"1\"\n"), "mysql");
    }

    #[test]
    fn only_a_sqlite_url_names_a_file() {
        assert_eq!(sqlite_file("sqlite://app.db?mode=rwc"), Some("app.db"));
        assert_eq!(sqlite_file("sqlite:data/app.db"), Some("data/app.db"));
        assert_eq!(sqlite_file("sqlite::memory:"), None);
        assert_eq!(sqlite_file("mysql://root:@127.0.0.1:3306/shop"), None);
    }
}
